from .parser import rows


def _valid_qty(value):
    # A nonnegative base-10 integer written in plain decimal digits.
    return bool(value) and all('0' <= c <= '9' for c in value)


def import_text(text, store):
    report = {'seen': 0, 'imported': 0, 'rejected': 0, 'quantity': 0}
    for parts in rows(text):
        report['seen'] += 1
        if len(parts) != 3:
            report['rejected'] += 1
            continue
        sku = parts[0].strip()
        name = parts[1].strip()
        qty = parts[2].strip()
        if not sku or not name or not _valid_qty(qty):
            report['rejected'] += 1
            continue
        amount = int(qty)
        store.put(sku, name, amount)
        report['imported'] += 1
        report['quantity'] += amount
    return report

